+    if (!alreadyRun) {
+        // the non-const should not have got registered
+        QVERIFY(!QMetaType::fromName("QObjectTypeRegisteredAsConst *").isValid());
+    }
+
+    QMetaType mt = QMetaType::fromType<QObjectTypeRegisteredAsConst *>();
+    int id = mt.id();
+    alreadyRun = true;
+    QCOMPARE_NE(id, cid);
+}
